<script setup>
import { computed, onMounted, ref, watch } from 'vue';import { Search, WalletCards, ArrowDownLeft, ArrowUpRight, LockKeyhole, History } from '@lucide/vue'
import { api } from '../../services/api';import { authStore } from '../../stores/auth';import { uiStore } from '../../stores/ui';import { money, date } from '../../utils'
import PageHeader from '../../components/PageHeader.vue';import LoadingBlock from '../../components/LoadingBlock.vue';import EmptyState from '../../components/EmptyState.vue';import StatusBadge from '../../components/StatusBadge.vue';import BaseModal from '../../components/BaseModal.vue';import PaginationBar from '../../components/PaginationBar.vue'
const isAdmin=computed(()=>authStore.isAdmin.value),loading=ref(true),rows=ref([]),summary=ref(null),meta=ref({page:1,limit:20,total:0}),filters=ref({search:'',type:''}),modal=ref(''),selected=ref(null),transactions=ref([]),txMeta=ref({page:1,limit:20,total:0}),busy=ref(false),form=ref({transaction_type:'DEPOSIT',direction:'CREDIT',amount:'',note:''});let debounce
async function load(page=1){loading.value=true;try{const [wallets,finance]=await Promise.all([api.get('/wallets',{page,limit:20,...filters.value}),isAdmin.value?api.get('/finance/summary'):Promise.resolve({data:null})]);rows.value=wallets.data;meta.value=wallets.meta;summary.value=finance.data}catch(e){uiStore.notify(e.message,'error')}finally{loading.value=false}}
watch(filters,()=>{clearTimeout(debounce);debounce=setTimeout(()=>load(1),300)},{deep:true});onMounted(()=>load())
function openAction(row){selected.value=row;form.value={transaction_type:'DEPOSIT',direction:'CREDIT',amount:'',note:''};modal.value='action'}
async function saveAction(){busy.value=true;try{await api.post(`/wallets/${selected.value.id}/actions`,form.value);uiStore.notify('Đã cập nhật ví và ghi sổ giao dịch.');modal.value='';load(meta.value.page)}catch(e){uiStore.notify(e.message,'error')}finally{busy.value=false}}
async function openHistory(row,page=1){selected.value=row;modal.value='history';try{const r=await api.get(`/wallets/${row.id}/transactions`,{page,limit:20});transactions.value=r.data;txMeta.value=r.meta}catch(e){uiStore.notify(e.message,'error')}}
async function toggleStatus(row){const status=row.status==='ACTIVE'?'LOCKED':'ACTIVE';try{await api.patch(`/wallets/${row.id}/status`,{status});uiStore.notify(`Đã ${status==='ACTIVE'?'mở':'khóa'} ví.`);load(meta.value.page)}catch(e){uiStore.notify(e.message,'error')}}
function onType(){if(['DEPOSIT','BONUS','REFUND'].includes(form.value.transaction_type))form.value.direction='CREDIT';else if(form.value.transaction_type!=='ADJUSTMENT')form.value.direction='DEBIT'}
</script>
<template><div><PageHeader eyebrow="Finance Center" title="Tài chính và ví" description="Mỗi CLB, cầu thủ, ban huấn luyện và Quỹ FIFA có ví riêng; mọi biến động đều được ghi lịch sử."></PageHeader><div v-if="isAdmin&&summary" class="grid-4 summary-grid"><article v-for="item in summary.wallets" :key="item.wallet_type" class="glass stat-card"><WalletCards :size="18" class="text-primary"/><div class="stat-value">{{ money(item.total_balance,true) }}</div><div class="stat-label">{{ item.wallet_type }} · {{ item.wallet_count }} ví</div></article></div><div class="glass card toolbar"><div class="toolbar-actions"><div class="search"><Search :size="17"/><input v-model="filters.search" class="input" placeholder="Tìm ví, CLB, cầu thủ..."/></div><select v-if="isAdmin" v-model="filters.type" class="select"><option value="">Tất cả loại ví</option><option value="FIFA">Quỹ FIFA</option><option value="CLUB">CLB</option><option value="PLAYER">Cầu thủ</option><option value="STAFF">Ban huấn luyện</option></select></div><span class="muted">{{ meta.total }} ví</span></div><LoadingBlock v-if="loading"/><EmptyState v-else-if="!rows.length"/><div v-else class="glass card table-card"><div class="table-wrap"><table><thead><tr><th>Ví</th><th>Chủ sở hữu</th><th>Loại</th><th>Số dư</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><b>{{ row.wallet_code }}</b></td><td>{{ row.owner_name }}</td><td><span class="badge blue">{{ row.wallet_type }}</span></td><td><b>{{ money(row.balance) }}</b></td><td><StatusBadge :status="row.status"/></td><td><div class="actions"><button class="btn btn-sm" @click="openHistory(row)"><History :size="14"/>Lịch sử</button><button v-if="isAdmin" class="btn btn-sm btn-primary" @click="openAction(row)"><ArrowUpRight :size="14"/>Giao dịch</button><button v-if="isAdmin" class="btn btn-sm" @click="toggleStatus(row)"><LockKeyhole :size="14"/>{{ row.status==='ACTIVE'?'Khóa':'Mở' }}</button></div></td></tr></tbody></table></div><PaginationBar v-bind="meta" @change="load"/></div><BaseModal :open="modal==='action'" :title="`Giao dịch ví ${selected?.wallet_code||''}`" @close="modal=''" width="560px"><form class="form-grid" @submit.prevent="saveAction"><label><span class="label">Loại giao dịch</span><select v-model="form.transaction_type" class="select" @change="onType"><option value="DEPOSIT">Nạp tiền</option><option value="WITHDRAWAL">Rút tiền</option><option value="BONUS">Thưởng</option><option value="PENALTY">Phạt</option><option value="ADJUSTMENT">Điều chỉnh</option><option value="REFUND">Hoàn tiền</option></select></label><label><span class="label">Chiều tiền</span><select v-model="form.direction" class="select" :disabled="form.transaction_type!=='ADJUSTMENT'"><option value="CREDIT">Cộng vào ví</option><option value="DEBIT">Trừ khỏi ví</option></select></label><label class="form-group full"><span class="label">Số tiền (VND)</span><input v-model="form.amount" type="number" min="1" class="input" required/></label><label class="form-group full"><span class="label">Nội dung</span><textarea v-model="form.note" class="textarea" required placeholder="Lý do giao dịch..."/></label><div class="form-group full actions"><button class="btn" type="button" @click="modal=''">Hủy</button><button class="btn btn-primary" :disabled="busy">Xác nhận một lần</button></div></form></BaseModal><BaseModal :open="modal==='history'" :title="`Lịch sử ${selected?.owner_name||''}`" @close="modal=''" width="900px"><div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Loại</th><th>Nội dung</th><th>Số tiền</th><th>Số dư sau</th></tr></thead><tbody><tr v-for="t in transactions" :key="t.id"><td>{{ date(t.created_at,true) }}</td><td>{{ t.transaction_type }}</td><td>{{ t.note }}</td><td :class="t.direction==='CREDIT'?'text-green':'text-red'"><b>{{ t.direction==='CREDIT'?'+':'-' }}{{ money(t.amount) }}</b></td><td>{{ money(t.balance_after) }}</td></tr></tbody></table></div><PaginationBar v-bind="txMeta" @change="p=>openHistory(selected,p)"/></BaseModal></div></template>
<style scoped>.summary-grid{margin-bottom:20px}.toolbar{margin-bottom:18px;padding:13px}.search{display:flex;align-items:center;gap:8px;min-width:300px}.search .input{border:0;background:transparent;box-shadow:none}.toolbar .select{width:180px}.table-card{padding:0;overflow:hidden}.actions{display:flex;gap:6px;justify-content:flex-end;flex-wrap:wrap}.form-group.full.actions{display:flex;justify-content:flex-end;gap:9px}@media(max-width:650px){.search{min-width:100%}.toolbar .select{width:100%}}</style>
